  1	/**
  2	 * Queue reading internals for the orchestrator run queue (WP-B extraction).
  3	 *
  4	 * Reads `.run-queue.json`, enriches each raw entry with computed lifecycle
  5	 * state and JSONL progress data, and returns the result as `QueueEntry[]`.
  6	 *
  7	 * This module is read-only with respect to the queue file and all other files.
  8	 *
  9	 * Exports beyond `getQueue()`:
 10	 *   - `readQueueFile` — used by `checkNoConflict` in `orchestrator-manager.ts`.
 11	 *   - `isProcessAlive` — used by queue-mutation functions in `orchestrator-manager.ts`.
 12	 *   - `getProjectLedgerStatus` — used by `killQueueEntry`/`dismissQueueEntry`
 13	 *     in `orchestrator-manager.ts`.
 14	 */
 15	
 16	import { readFile } from 'node:fs/promises';
 17	import { join } from 'node:path';
 18	
 19	import { QUEUE_FILENAME, type RawQueueEntry, type QueueEntry } from './types.js';
 20	import { resolveProgress } from './resolve-progress.js';
 21	import { computeEffectiveStatus } from './compute-effective-status.js';
 22	
 23	// ---------------------------------------------------------------------------
 24	// PID alive check
 25	// ---------------------------------------------------------------------------
 26	
 27	/**
 28	 * Returns `true` if the process with `pid` exists on this machine.
 29	 *
 30	 * Uses `process.kill(pid, 0)` which is a zero-signal check — it only
 31	 * verifies the process exists and does not actually deliver any signal.
 32	 *
 33	 * Exported for use by queue-mutation functions in `orchestrator-manager.ts`.
 34	 */
 35	export function isProcessAlive(pid: number): boolean {
 36	  try {
 37	    process.kill(pid, 0);
 38	    return true;
 39	  } catch {
 40	    return false;
 41	  }
 42	}
 43	
 44	// ---------------------------------------------------------------------------
 45	// Queue file reader
 46	// ---------------------------------------------------------------------------
 47	
 48	/**
 49	 * Reads and parses `<logsDir>/.run-queue.json`.
 50	 * Returns `[]` on any I/O or parse error — fail-safe.
 51	 * Never writes to the queue file.
 52	 *
 53	 * Exported for use by `checkNoConflict` in `orchestrator-manager.ts`.
 54	 */
 55	export async function readQueueFile(logsDir: string): Promise<RawQueueEntry[]> {
 56	  const queuePath = join(logsDir, QUEUE_FILENAME);
 57	  let raw: string;
 58	  try {
 59	    raw = await readFile(queuePath, 'utf-8');
 60	  } catch {
 61	    return [];
 62	  }
 63	  try {
 64	    const data: unknown = JSON.parse(raw);
 65	    if (!Array.isArray(data)) return [];
 66	    return data.filter(isRawQueueEntry);
 67	  } catch {
 68	    return [];
 69	  }
 70	}
 71	
 72	function isRawQueueEntry(entry: unknown): entry is RawQueueEntry {
 73	  if (typeof entry !== 'object' || entry === null) return false;
 74	  const e = entry as Record<string, unknown>;
 75	  return (
 76	    typeof e['id'] === 'string' &&
 77	    typeof e['pid'] === 'number' && Number.isInteger(e['pid']) && (e['pid'] as number) > 0 &&
 78	    typeof e['planPath'] === 'string' &&
 79	    typeof e['expectedSlug'] === 'string' &&
 80	    typeof e['startedAt'] === 'string'
 81	  );
 82	}
 83	
 84	// ---------------------------------------------------------------------------
 85	// Project ledger check
 86	// ---------------------------------------------------------------------------
 87	
 88	/**
 89	 * Returns whether the project identified by `slug` has a ledger entry and
 90	 * whether synthesis has been generated for it.
 91	 *
 92	 * Fail-safe: any I/O or parse error returns `{ exists: false, synthesisGenerated: false }`.
 93	 *
 94	 * Exported for use by `killQueueEntry`/`dismissQueueEntry` in `orchestrator-manager.ts`.
 95	 *
 96	 * @param ledgerRoot - Absolute path to the ledger root directory.
 97	 * @param slug       - Project slug (e.g. `2026-05-05-my-feature`).
 98	 */
 99	export async function getProjectLedgerStatus(
100	  ledgerRoot: string,

101	  slug: string,
102	): Promise<{ exists: boolean; synthesisGenerated: boolean }> {
103	  const projectLedgerPath = join(ledgerRoot, slug, 'project-ledger.json');
104	  let raw: string;
105	  try {
106	    raw = await readFile(projectLedgerPath, 'utf-8');
107	  } catch {
108	    return { exists: false, synthesisGenerated: false };
109	  }
110	  try {
111	    const data = JSON.parse(raw) as Record<string, unknown>;
112	    return {
113	      exists: true,
114	      synthesisGenerated: data['synthesis_generated'] === true,
115	    };
116	  } catch {
117	    return { exists: true, synthesisGenerated: false };
118	  }
119	}
120	
121	// ---------------------------------------------------------------------------
122	// Public API
123	// ---------------------------------------------------------------------------
124	
125	/**
126	 * Reads the shared orchestrator run queue and returns all active entries
127	 * enriched with computed lifecycle state and JSONL progress summaries.
128	 *
129	 * Entries for completed projects (`synthesis_generated === true`) are
130	 * automatically excluded from the result.
131	 *
132	 * This function is read-only: it never writes to the queue file or any
133	 * other file on disk.
134	 *
135	 * @param params.logsDir    - Absolute path to `orchestrator/logs/`.
136	 * @param params.ledgerRoot - Absolute path to the central ledger root.
137	 * @returns Enriched queue entries, excluding completed runs.
138	 */
139	export async function getQueue(params: {
140	  logsDir: string;
141	  ledgerRoot: string;
142	}): Promise<QueueEntry[]> {
143	  const { logsDir, ledgerRoot } = params;
144	
145	  const rawEntries = await readQueueFile(logsDir);
146	  if (rawEntries.length === 0) return [];
147	
148	  const enriched = await Promise.all(
149	    rawEntries.map(async (entry) => {
150	      const [projectStatus, progressResult] = await Promise.all([
151	        getProjectLedgerStatus(ledgerRoot, entry.expectedSlug),
152	        resolveProgress(logsDir, entry.expectedSlug),
153	      ]);
154	
155	      const { exists: projectExists, synthesisGenerated } = projectStatus;
156	      const alive = isProcessAlive(entry.pid);
157	
158	      // Compute effective status per AC-2 through AC-5.
159	      const effectiveStatus = computeEffectiveStatus(alive, projectExists, progressResult.hasStageActivity);
160	
161	      // AC-6: exclude entries whose project has completed synthesis.
162	      if (effectiveStatus === 'started' && synthesisGenerated) {
163	        return null;
164	      }
165	
166	      const result: QueueEntry = {
167	        ...entry,
168	        effectiveStatus,
169	        progress:    progressResult.summary,
170	        lastAction:  progressResult.lastAction,
171	        logFilename: progressResult.logFilename,
172	      };
173	      return result;
174	    }),
175	  );
176	
177	  return enriched.filter((e): e is QueueEntry => e !== null);
178	}

